## Submitted testbench
```systemverilog
module tb;
  // ------------------------------------------------------------
  // Parameters
  // ------------------------------------------------------------
  localparam int CLK_PERIOD = 8;                // 125 MHz clock
  localparam logic [15:0] PRESCALE = 16'd5;     // Baud prescale used by the DUT

  // ------------------------------------------------------------
  // Clock and reset
  // ------------------------------------------------------------
  logic clk = 0;
  logic rst   = 0;

  // ------------------------------------------------------------
  // DUT signals
  // ------------------------------------------------------------
  logic [7:0]  m_axis_tdata;
  logic        m_axis_tvalid;
  logic        m_axis_tready;   // driven by this testbench
  logic        rxd      = 1'b1; // UART receive line
  logic [15:0] prescale = PRESCALE; // configuration input

  // -----------------------------------------------------------------
  // Instantiate the uart_rx module (default parameters)
  // -----------------------------------------------------------------
  uart_rx #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),
    .m_axis_tdata (m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready), // input  – driven by tb
    .rxd          (rxd),
    .busy         (),               // unused
    .overrun_error(),               // unused
    .frame_error  (),               // unused
    .prescale     (prescale)        // configuration input
  );

  // ------------------------------------------------------------
  // Clock generation
  // ------------------------------------------------------------
  always #(CLK_PERIOD/2) clk = ~clk;

  // ------------------------------------------------------------
  // Reset sequence
  // ------------------------------------------------------------
  initial begin
    rst = 0;
    #(CLK_PERIOD*2);
    rst = 1;
    #(CLK_PERIOD*2);
    rst = 0;
    #(CLK_PERIOD*2);
  end

  // ------------------------------------------------------------
  // Task: transmit a byte on the rxd line (8N1, LSB first)
  // ------------------------------------------------------------
  task automatic send_byte(input byte unsigned b);
    // start bit
    rxd = 1'b0;
    repeat (PRESCALE) @(negedge clk); // 1 bit time

    // 8 data bits, LSB first
    for (int i = 0; i < 8; i++) begin
      rxd = b[i];
      repeat (PRESCALE) @(negedge clk);
    end

    // stop bit
    rxd = 1'b1;
    repeat (PRESCALE) @(negedge clk);
  endtask

  // ------------------------------------------------------------
  // Main stimulus
  // ------------------------------------------------------------
  initial begin
    // Wait for reset release
    @(negedge rst);
    #1; // small margin

    // ---- First frame : payload 0x3C (will be stalled) ----
    send_byte(8'h3C);
    // Give the DUT time to sample the frame; keep ready low
    repeat (30) @(negedge clk);

    // ---- Second frame : payload 0xC3 (target newest word) ----
    send_byte(8'hC3);
    // Allow an overrun pulse to be generated while the sink is still stalled
    repeat (10) @(negedge clk);

    // Wait until the receiver signals that a new word is available
    // (m_axis_tvalid goes high) and then drive the handshake.
    @(negedge m_axis_tvalid); // wait for the falling edge of the previous cycle
    repeat (5) @(negedge clk); // give the design a couple of cycles to raise m_axis_tvalid

    // Drive the sink ready high – this completes the handshake
    m_axis_tready = 1'b1;

    // Allow the handshake to be observed by the coverage model
    repeat (10) @(negedge clk);

    // End of simulation – the coverage point must have been hit
    $finish;
  end
endmodule
```

